div.script:
                    $(document).ready(function() {
                        console.log("Test page loaded");

                        // Make a direct call to the RPC endpoint
                        odoo.jsonRpc("/upcoming_sessions/data", 'call', {
                            limit: 10
                        }).then(function(data) {
                            console.log("Success!", data);

                            if (data && data.length) {
                                var html = "";
                                data.forEach(function(session) {
                                    html += "
" + session.name + " - " + session.formatted_date + "";
                                });
                                html += "";
                                $("#test-result").html(html);
                            } else {
                                $("#test-result").html("No sessions found");
                            }
                        }).guardedCatch(function(error) {
                            console.error("Error:", error);
                            $("#test-result").html("Error: " + JSON.stringify(error));
                        });
                    });
